from collections import deque,Counter
def f(g):
    h,w=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    out=[r[:] for r in g]
    seen=[[False]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if g[i][j]==bg and not seen[i][j]:
                q=deque([(i,j)]); seen[i][j]=True; cells=[]
                touches=False
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    if a in(0,h-1) or b in(0,w-1): touches=True
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<h and 0<=y<w and g[x][y]==bg and not seen[x][y]:
                            seen[x][y]=True; q.append((x,y))
                if not touches:
                    v=2 if len(cells)%2==0 else 7
                    for a,b in cells: out[a][b]=v
    return out
for k in ['Demo pair 1','Demo pair 2']:
    ok = f(G[k+' input'])==G[k+' output']
    print(k, ok)
print(json.dumps(f(G['Test input'])))
